async function processMapOAuthGrants(clientId) {
  const { data: { session }} = await se.auth.getSession();
  if (!session) throw new Error("No ProcessMap session");
  const url = new URL("/auth/v1/user/oauth/grants", window.PM_CONFIG.url);
  if (clientId !== undefined) url.searchParams.set("client_id", clientId);
  const response = await fetch(url, {
    method: clientId === undefined ? "GET" : "DELETE",
    headers: { apikey: window.PM_CONFIG.key, Authorization: "Bearer " + session.access_token },
    redirect: "error",
  });
  if (!response.ok) throw new Error("OAuth grants are unavailable");
  if (clientId === undefined) {
    const grants = await response.json();
    if (!Array.isArray(grants)) throw new Error("Unexpected OAuth grant response");
    return grants;
  }
}
